const params=new URLSearchParams(location.search);
const state={route:routes.some(r=>r.id===params.get('screen'))?params.get('screen'):'tasks-list',theme:params.get('theme')==='dark'?'dark':'light',review:['loading','empty','error','stale'].includes(params.get('state'))?params.get('state'):'full',selectedTask:'DEMO-104',modal:null,labInspector:true,labSelection:'Список',labPaused:false};
const route=id=>routes.find(r=>r.id===id);
const current=()=>route(state.route);
const href=id=>`?screen=${encodeURIComponent(id)}&theme=${state.theme}${state.review==='full'?'':`&state=${state.review}`}`;
const link=(id,text,cls='',symbol='')=>`<a href="${href(id)}" data-route="${id}" class="${cls}">${symbol?icon(symbol):''}${text}</a>`;
const btn=(text,symbol='',attrs='')=>`<button type="button" ${attrs}>${symbol?icon(symbol):''}${text}</button>`;
const demo=(text,symbol='',cls='')=>btn(text,symbol,`class="${cls}" data-demo="${escape(text)}"`);
const badge=(text,tone='neutral',symbol='')=>`<span class="badge ${tone}">${symbol?icon(symbol):''}${text}</span>`;
const callout=(title,text,tone='amber',symbol='warning',actions='')=>`<div class="callout ${tone}">${icon(symbol)}<div><h3>${title}</h3><p>${text}</p>${actions?`<div class="actions">${actions}</div>`:''}</div></div>`;
const props=items=>`<dl class="properties">${items.map(([key,value])=>`<dt>${key}</dt><dd>${value}</dd>`).join('')}</dl>`;
const field=(label,value='',options={})=>{const id=options.id||`f-${label.replace(/[^a-zа-яё0-9]/gi,'').toLowerCase()}`;let control;if(options.kind==='textarea')control=`<textarea id="${id}" ${options.rows?`rows="${options.rows}"`:''}>${escape(value)}</textarea>`;else if(options.options)control=`<select id="${id}" ${options.multiple?'multiple':''}>${options.options.map(v=>`<option ${v===value?'selected':''}>${escape(v)}</option>`).join('')}</select>`;else control=`<input id="${id}" type="${options.type||'text'}" value="${escape(value)}" ${options.readonly?'readonly':''} ${options.placeholder?`placeholder="${escape(options.placeholder)}"`:''}>`;return `<div class="field ${options.full?'full':''}"><label for="${id}">${label}</label>${control}${options.hint?`<small>${options.hint}</small>`:''}</div>`;};
const check=(label,id,attrs='')=>`<label class="check"><input type="checkbox" id="${id}" ${attrs}><span>${label}</span></label>`;
const formActions=(primary='Сохранить',secondary='Отмена',extra='')=>`<div class="form-actions"><span class="meta">Демонстрация интерфейса</span>${extra}${demo(secondary)}${demo(primary,'','primary')}</div>`;
const title=(heading,description,actions='')=>`<div class="page-title"><div><h1>${heading}</h1>${description?`<p>${description}</p>`:''}</div><div class="title-actions">${actions}</div></div>`;
const code=text=>`<pre class="code-block">${escape(text)}</pre>`;
const tabs=(items,active,cls='segmented')=>{const isTab=cls!=='local-nav'&&cls!=='workflow-nav'&&items.some(([id])=>id===active);const panel=cls==='inspector-tabs'?'task-tabpanel':cls==='conversation-tabs'?'session-tabpanel':'review-route-panel';return `<div class="${cls}" ${isTab?'role="tablist"':''} aria-label="Вложенные разделы" data-tabset="${cls}">${items.map(([id,text])=>`<a href="${href(id)}" data-route="${id}" class="${id===active?'active':''}" ${isTab?`id="tab-${id}" role="tab" aria-selected="${id===active}" tabindex="${id===active?0:-1}" aria-controls="${panel}"`:(id===active?'aria-current="page"':'')}>${text}</a>`).join('')}</div>`;};
const rows=(headers,data,classes=[])=>`<table class="data-list"><thead><tr>${headers.map((h,i)=>`<th scope="col" class="${classes[i]||''}">${h}</th>`).join('')}</tr></thead><tbody>${data.map(row=>`<tr>${row.map((cell,i)=>`<td class="${classes[i]||''}">${cell}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const activity=items=>`<ul class="activity">${items.map(([symbol,text,meta])=>`<li><span class="event-icon">${icon(symbol)}</span><div>${text}<small>${meta}</small></div></li>`).join('')}</ul>`;
const sourceHint=()=>`<div class="route-source">Основание макета: ${current().source.file}:${current().source.line}. ${current().provenance==='proposed_organization'?'Предложена новая организация существующей панели.':current().provenance==='review_only'?'Только лаборатория дизайна.':'Сохранены действия существующей поверхности.'}</div>`;
