for(const id of ['sessions-work','sessions-history'])metaPatch(id,{source:{file:'apps/web/src/features/sessions/SessionsCatalog.tsx',line:41},provenance:'actual_tab'});
for(const id of ['session-context','session-changes'])metaPatch(id,{provenance:'actual_tab'});
for(const [id,line] of [['session-run',15],['session-checks',87],['session-question',150]])metaPatch(id,{source:{file:SOURCE.session,line},provenance:'source_panel'});
metaPatch('task-delete',{source:{file:SOURCE.task,line:90},provenance:'source_panel'});
