for(const id of ['agents-history','skills-history'])metaPatch(id,{preservedActions:['История версий','Подготовить восстановление']});
for(const id of ['import-source','import-preview','import-export'])metaPatch(id,{source:{file:'apps/web/src/ui/Operations.tsx',line:163}});
metaPatch('import-export',{preservedActions:['Reverse export','Скачать JSON']});
for(const id of ['backup-create','backup-restore'])metaPatch(id,{source:{file:'apps/web/src/ui/Operations.tsx',line:468}});
metaPatch('task-archive',{source:{file:SOURCE.manager,line:54},preservedActions:['Экспорт полного профиля','Backup ID','Подтверждение восстановления','Restart']});
