window.DESIGN_COVERAGE={version:2,scope:'desktop_design_only',themes:['light','dark'],routes,fixturePolicy:'All data synthetic; no APIs, credentials or storage',coverageCeiling:'Review specimens preserve source actions; not runtime implementation'};

function sectionTabs(){const group=current().group;if(group==='settings')return '';let items=[];if(group==='overview')items=[['overview','Рабочий обзор'],['overview-sources','Источники']];if(group==='tasks')items=[['tasks-list','Задачи'],['task-components','Настройки задач'],['task-archive','Полный архив']];if(group==='sessions')items=[['sessions-work','Работа'],['sessions-history','Полная доступная история']];if(group==='agents')items=[['agents-profile','Каталог профилей'],['agents-generate','Предложение агента']];if(group==='skills')items=[['skills-profile','Каталог скиллов'],['skills-discover','Источники и импорт'],['skill-requirements','Генератор скиллов']];if(group==='graph')items=[['graph-map','Граф исходников'],['graph-list','Клавиатурный список']];if(group==='documents')items=[['documents-list','Каталог'],['document-reader','Документ'],['document-proposal','Предложение']];if(group==='checks')items=[['checks-list','Все проверки'],['check-detail','Результат и приёмка']];if(group==='autonomy')items=[['autonomy-policy','Политика'],['autonomy-runs','Запуски и остановка']];if(group==='decisions')items=[['decisions-list','Требуют ответа'],['decision-history','История решений']];if(group==='import')items=[['import-source','Импорт'],['import-export','Обратный экспорт']];if(group==='backup')items=[['backup-create','Создание и ротация'],['backup-restore','Восстановление']];if(group==='settings')items=[['settings-general','Среда'],['workflow-catalog','Процессы'],['recipe-preview','Выполнение'],['execution-queue','Очередь']];if(group==='search')items=[['search','Все результаты']];if(group==='lab')items=[['component-lab','Компоненты'],['motion-lab','Движение']];return items.map(([id,text])=>link(id,text,id===state.route?'active':'')).join('');}
function bodyForRoute(){const r=current();if(r.group==='overview')return overview(r.kind);if(r.group==='tasks')return renderTasks();if(r.group==='sessions')return sessionScreen(r.kind);if(['agents','skills'].includes(r.group))return teamScreen();if(r.group==='graph')return graphScreen(r.kind);if(r.group==='documents')return documentScreen(r.kind);if(r.group==='checks')return checkScreen(r.kind);if(r.group==='autonomy')return autonomyScreen(r.kind);if(r.group==='decisions')return decisionsScreen(r.kind);if(r.group==='search')return searchScreen();if(r.group==='import')return importScreen(r.kind);if(r.group==='backup')return backupScreen(r.kind);if(r.group==='lab')return labScreen(r.kind);if(r.id.startsWith('workflow-'))return workflowScreen(r.kind);if(r.id.startsWith('recipe-')||r.id==='execution-queue')return recipeScreen(r.kind);return settingsScreen(r.kind);}
const emptyCopy={overview:['Источники ещё не прочитаны','Обновите доступные источники проекта.'],tasks:['Подходящих задач нет','Измените фильтры или создайте первую задачу.'],sessions:['Сессий пока нет','Создайте сессию и выберите контекст задачи.'],agents:['Профили не найдены','Проверьте доступные источники или подготовьте проектное предложение.'],skills:['Скиллы не найдены','Проверьте источники или опишите потребность для предложения.'],graph:['Узлов не найдено','Измените запрос или проверьте состояние индекса.'],documents:['Документы не найдены','Проверьте источники и выбранный тип материала.'],checks:['Проверок пока нет','Запустите допустимую проверку через сессию.'],autonomy:['Учтённых запусков нет','Настройте границы и проверьте допуск политики.'],decisions:['Нет решений, ожидающих ответа','Новые вопросы появятся с привязкой к задаче и запуску.'],search:['Совпадений не найдено','Сократите запрос или измените фильтры.'],import:['Кандидатов нет','Проверьте выбранный исходный файл и projection.'],backup:['Receipt пока нет','Создайте копию и проверьте её manifest.'],settings:['Нет записей в выбранном разделе','Добавьте или выберите существующий объект.'],lab:['Пустое состояние примера','Состояние выбирается только для проверки дизайна.']};
function applyReviewState(content){if(state.review==='full')return content;const r=current();if(state.review==='loading')return title(r.title,'Просмотр состояния загрузки. Рабочий контекст сохраняется.')+`<section class="surface" aria-busy="true"><div class="skeleton-label"><span class="spinning">${icon('loader')}</span>Читаем ${GROUPS[r.group][0].toLowerCase()}…</div>${skeletonRows(5)}<p class="meta mt16">Состояние макета. Запрос к приложению не выполняется.</p></section>`;if(state.review==='empty'){const [head,text]=emptyCopy[r.group];return title(r.title,'Просмотр пустого состояния.')+`<section class="empty-region">${icon(GROUPS[r.group][1])}<h2>${head}</h2><p>${text}</p>${btn('Вернуться к примеру','refresh','class="secondary-button" data-action="review-full"')}</section>`;}const banner=state.review==='error'?callout('Не удалось получить актуальные данные','Проверьте подключение и повторите чтение. Показанный контекст не считается свежим. Черновик остаётся доступен.','coral','warning',btn('Повторить','refresh','data-action="review-full"')):callout('Источник изменился','Отображается предыдущая доступная версия. Обновите source revision перед действием; старые anchors и previews не считаются актуальными.','amber','history',btn('Обновить источник','refresh','data-action="review-full"'));return banner+content;}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function render(){document.documentElement.dataset.theme=state.theme;document.title=`${current().title}: Product-Agent OS`;document.querySelector('#section-name').textContent=GROUPS[current().group][0];document.querySelector('#nav').innerHTML=NAV_GROUPS.map(([label,groups])=>`<div class="nav-group"><div class="nav-group-label">${label}</div>${groups.map(group=>{const [text,symbol,id]=GROUPS[group];return `<a href="${href(id)}" data-route="${id}" data-section="${group}" class="nav-link ${group===current().group?'active':''}" ${group===current().group?'aria-current="page"':''}><span class="nav-icon">${icon(symbol)}</span>${text}</a>`;}).join('')}</div>`).join('');document.querySelector('#section-tabs').innerHTML=sectionTabs();document.querySelector('#section-tabs').hidden=current().group==='settings';document.querySelector('main').innerHTML=`<section data-content-route="${state.route}" id="review-route-panel">${applyReviewState(bodyForRoute())}</section>${sourceHint()}`;document.querySelector('#review-position').textContent=`${routes.findIndex(r=>r.id===state.route)+1} / ${routes.length}`;document.querySelector('#review-state').value=state.review;document.querySelector('#theme-name').textContent=state.theme==='dark'?'Obsidian':'Porcelain';document.querySelector('#theme-switch [data-icon]').dataset.icon=state.theme==='dark'?'sun':'moon';hydrateIcons();if(state.route==='task-move'&&state.review==='full')openTaskMove();if(state.route==='task-delete'&&state.review==='full')openTaskDelete();window.DESIGN_RENDER_READY={id:state.route,theme:state.theme,state:state.review};}
function navigate(id,{replace=false,focus=true}={}){if(!route(id))throw new Error(`Unknown review route: ${id}`);closeModal(false);state.route=id;history[replace?'replaceState':'pushState'](null,'',href(id));render();window.scrollTo(0,0);if(focus&&!state.modal)document.querySelector('main').focus({preventScroll:true});}
let toastTimer,lastFocus;
function toast(message){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.innerHTML=icon('eye')+`<span>${escape(message)}</span>`;el.hidden=false;toastTimer=setTimeout(()=>{el.hidden=true;},4500);}
function showDemo(label){toast(`Демонстрация: ${label}. Данные приложения не изменяются.`);}
function openModal(titleText,content,footer='',wide=false){lastFocus=document.activeElement;state.modal=true;document.querySelector('#modal-root').innerHTML=`<div class="modal-scrim" data-backdrop><section class="modal ${wide?'catalog-modal':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="modal-header"><h2 id="dialog-title">${titleText}</h2>${btn('','close','class="icon-button" data-action="close-modal" aria-label="Закрыть диалог"')}</header><div class="${wide?'catalog-body':'modal-body'}">${content}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;document.querySelector('.app-shell').inert=true;document.querySelector('.review-ribbon').inert=true;document.querySelector('.modal button,.modal input,.modal select,.modal a')?.focus();}
function closeModal(restore=true){document.querySelector('#modal-root').innerHTML='';document.querySelector('.app-shell').inert=false;document.querySelector('.review-ribbon').inert=false;state.modal=false;if(restore&&lastFocus?.isConnected)lastFocus.focus();}
function openTaskMove(){openModal('Перевести задачу',`<p class="readable">DEMO-104 / Обновить навигацию проекта</p>${field('Целевое состояние','На ревью',{options:['На ревью','Проверка','Ожидает приёмки'],id:'move-target'})}<p class="meta">Далее откроются действующие критерии и проверки перехода. Состояние не меняется при выборе.</p>`,btn('Отмена','','data-action="close-route-modal"')+link('task-acceptance','Перейти к проверкам','primary','right'));}
function openTaskDelete(){openModal('Удалить задачу?',`<p class="readable">DEMO-104 / Обновить навигацию проекта</p>${callout('Связанные записи сохраняются','Удаление задачи не запускает каскадное удаление связанных сессий и материалов.','amber','warning')}${check('Подтверждаю удаление задачи без каскадного удаления связанных записей','task-delete-confirm','data-enable="task-delete-button"')}`,btn('Отмена','','data-action="close-route-modal"')+btn('Удалить задачу','trash','id="task-delete-button" disabled class="danger-button" data-demo="Удаление задачи"'));}
function openCatalog(){openModal('Все экраны альбома',`<label class="search-field catalog-search">${icon('search')}<input id="catalog-query" type="search" placeholder="Название, раздел или ID экрана" aria-label="Найти экран"></label><p class="meta mb16">80 содержательных экранов. Переключение темы доступно в нижней панели.</p><div class="screen-catalog">${routes.map(r=>`<a href="${href(r.id)}" data-route="${r.id}" class="${r.id===state.route?'active':''}" data-catalog-item data-search="${escape(`${r.title} ${r.id} ${GROUPS[r.group][0]}`.toLowerCase())}"><strong>${r.title}</strong><small>${GROUPS[r.group][0]} / ${r.id}</small></a>`).join('')}</div>`,'',true);}
let menuTrigger;
function menuAt(control,items){menuTrigger=control;const existing=document.querySelector('#context-menu');if(existing){existing.remove();return;}const container=document.createElement('span');container.className='popover';container.id='context-menu';container.innerHTML=items;control.parentElement.style.position='relative';control.parentElement.append(container);control.setAttribute('aria-expanded','true');container.querySelector('button,a')?.focus();}
document.addEventListener('click',async event=>{
 const control=event.target.closest('a,button');
 if(event.target.matches('[data-backdrop]')){closeModal();return;}
 if(!control)return;
 if(control.dataset.route){event.preventDefault();const targetRoute=control.dataset.route;const isTab=control.getAttribute('role')==='tab';navigate(targetRoute,{focus:!isTab});if(isTab)document.querySelector(`[role=tab][data-route="${targetRoute}"]`)?.focus({preventScroll:true});return;}
 if(control.dataset.demo){event.preventDefault();showDemo(control.dataset.demo);return;}
 if(control.dataset.transition!==undefined){const index=Number(control.dataset.transition);document.querySelectorAll('[data-transition]').forEach(el=>{el.classList.toggle('selected-transition',el===control);el.setAttribute('aria-pressed',String(el===control));});const [id,text]=WORKFLOW_TRANSITIONS[index];const [from,to]=id.split('-');document.querySelector('#transition-title').textContent=text;document.querySelector('#transition-id').value=id;document.querySelector('#transition-name').value=text;document.querySelector('#transition-from').value=from;document.querySelector('#transition-to').value=to;document.querySelector('#transition-checks').value=to==='done'?'criteria,dependencies,children,blocker':'';document.querySelector('#actor-user').checked=true;document.querySelector('#actor-agent').checked=to!=='done';return;}
 if(control.dataset.labSelect){state.labSelection=control.dataset.labSelect;document.querySelectorAll('[data-lab-select]').forEach(el=>el.setAttribute('aria-pressed',String(el===control)));document.querySelector('#segment-feedback').textContent=`Выбрано: ${state.labSelection}. Меняется только представление примера.`;return;}
 const action=control.dataset.action;
 if(action==='close-modal'){if(['task-move','task-delete'].includes(state.route))navigate('task-summary');else closeModal();return;}
 if(action==='close-route-modal'){navigate('task-summary');return;}
 if(action==='review-full'){state.review='full';navigate(state.route,{replace:true});return;}
 if(action==='project-picker'){showDemo('Выбор проекта');return;}
 if(action==='profile-menu'){showDemo('Сведения о локальной среде');return;}
 if(action==='task-menu'){menuAt(control,link('task-create','Изменить задачу','','edit')+link('task-delete','Удалить задачу','','trash'));return;}
 if(action==='lab-menu'){const menu=document.querySelector('#lab-menu');menuTrigger=control;menu.hidden=!menu.hidden;control.setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden)menu.querySelector('button')?.focus();return;}
 if(action==='lab-copy'){control.innerHTML=`<span class="copied-icon">${icon('check')}</span>Скопировано / демо`;document.querySelector('#copy-feedback').textContent='Симуляция подтверждения: пример скопирован. Системный буфер не изменён.';return;}
 if(action==='lab-inspector'){const panel=document.querySelector('#motion-inspector');const visible=panel.hidden;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(visible){panel.hidden=false;if(!reduced)panel.animate([{opacity:0,transform:'translateX(12px)'},{opacity:1,transform:'translateX(0)'}],{duration:220,easing:'cubic-bezier(.2,.75,.25,1)'});}else if(reduced)panel.hidden=true;else{await panel.animate([{opacity:1,transform:'translateX(0)'},{opacity:0,transform:'translateX(12px)'}],{duration:140,easing:'ease-in'}).finished;panel.hidden=true;}control.setAttribute('aria-expanded',String(visible));control.innerHTML=icon('right')+(visible?'Скрыть панель':'Показать панель');return;}
 if(action==='lab-pause'){state.labPaused=true;document.querySelector('#lab-run-status').innerHTML=badge('Симуляция: на паузе','amber','pause');document.querySelector('#pause-feedback').textContent='Симуляция паузы. Реальный terminal ACK не создаётся.';control.disabled=true;document.querySelector('#lab-recover').disabled=false;return;}
 if(action==='lab-recover'){state.labPaused=false;document.querySelector('#lab-run-status').innerHTML=badge('Симуляция: возобновлено','sage','check');document.querySelector('#pause-feedback').textContent='Симуляция восстановления после сверки. Реальных команд нет.';control.disabled=true;document.querySelector('#lab-pause').disabled=false;return;}
});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.enable){const target=document.querySelector(`#${el.dataset.enable}`);if(target)target.disabled=!el.checked;}if(el.id==='review-state'){state.review=el.value;navigate(state.route,{replace:true});}});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.filter){const query=el.value.toLocaleLowerCase('ru');document.querySelectorAll(`[data-filter-row="${el.dataset.filter}"]`).forEach(row=>row.hidden=!row.dataset.filterValue.includes(query));}if(el.id==='catalog-query'){const query=el.value.toLocaleLowerCase('ru');document.querySelectorAll('[data-catalog-item]').forEach(row=>row.hidden=!row.dataset.search.includes(query));}if(el.id==='lab-progress'){document.querySelector('#lab-progress-output').textContent=`${el.value}%`;document.querySelector('#lab-progressbar').setAttribute('aria-valuenow',el.value);document.querySelector('#lab-progress-fill').style.setProperty('--progress',Number(el.value)/100);}});
document.addEventListener('focusout',event=>{if(event.target.id==='lab-process-id'){const valid=/^[a-z][a-z0-9-]*$/.test(event.target.value);event.target.setAttribute('aria-invalid',String(!valid));document.querySelector('#lab-validation').textContent=valid?'ID подходит для примера.':'Используйте латиницу, цифры и дефис; начните с буквы.';}});
document.addEventListener('keydown',event=>{const tablist=event.target.closest('[role=tablist]');if(tablist&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const items=[...tablist.querySelectorAll('[role=tab]')],at=items.indexOf(document.activeElement);const next=event.key==='Home'?0:event.key==='End'?items.length-1:(at+(event.key==='ArrowRight'?1:-1)+items.length)%items.length;const id=items[next].dataset.route;navigate(id,{focus:false});document.querySelector(`[role=tab][data-route="${id}"]`)?.focus({preventScroll:true});return;}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();navigate('search');return;}if(event.key==='Escape'){const contextMenu=document.querySelector('#context-menu');const popover=document.querySelector('#lab-menu');const wasMenu=!!contextMenu||(popover&&!popover.hidden);contextMenu?.remove();if(popover)popover.hidden=true;if(wasMenu&&menuTrigger?.isConnected){menuTrigger.setAttribute('aria-expanded','false');menuTrigger.focus();}if(state.modal){if(['task-move','task-delete'].includes(state.route))navigate('task-summary');else closeModal();}return;}if(event.key==='Tab'&&state.modal){const controls=[...document.querySelectorAll('.modal button:not([disabled]),.modal input,.modal select,.modal textarea,.modal a')].filter(el=>el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
document.querySelector('#previous').addEventListener('click',()=>navigate(routes[(routes.findIndex(r=>r.id===state.route)-1+routes.length)%routes.length].id));
document.querySelector('#next').addEventListener('click',()=>navigate(routes[(routes.findIndex(r=>r.id===state.route)+1)%routes.length].id));
document.querySelector('#catalog-button').addEventListener('click',openCatalog);
document.querySelector('#theme-switch').addEventListener('click',()=>{state.theme=state.theme==='light'?'dark':'light';navigate(state.route,{replace:true,focus:false});});
window.addEventListener('popstate',()=>{const query=new URLSearchParams(location.search);state.route=route(query.get('screen'))?query.get('screen'):'tasks-list';state.theme=query.get('theme')==='dark'?'dark':'light';state.review=['loading','empty','error','stale'].includes(query.get('state'))?query.get('state'):'full';closeModal(false);render();});

